import type { PageServerLoad } from './$types';
import fs from 'fs';
import path from 'path';
import { parsePrismaSchema } from '$lib/utils/parse-prisma-schema';
// The function should be named `load` and exported.
// The type `PageServerLoad` is generated by SvelteKit's type system ($types).
export const load: PageServerLoad = async () => {
	const prismaPath = path.join(process.cwd(), 'src/routes/models-handler', 'schema_prisma.ts');
	// log('prismaPath', prismaPath)
	const schema = fs.readFileSync(prismaPath, 'utf-8');
	// log('schema', schema)

	// log('parsePrismaSchema', parsePrismaSchema);
	const { models, enums } = parsePrismaSchema(schema);
	// log('MODELS', JSON.stringify(Object.fromEntries(models), null, 2))
	// log('ENUMS', JSON.stringify(Object.fromEntries(enums), null, 2))


	return { models, enums };
};
